class Solution {
    int memo[105][205];
    const int MOD = 1e9 + 7;
    int dp(int u, int f, int finish, const std::vector<int>& loc) {
        if (memo[u][f] != -1) return memo[u][f];
        int ans = (u == finish ? 1 : 0);
        int n = loc.size();
        for (int v = 0; v < n; ++v) {
            if (v != u) {
                int cost = std::abs(loc[u] - loc[v]);
                if (cost <= f) {
                    ans = (ans + dp(v, f - cost, finish, loc)) % MOD;
                }
            }
        }
        return memo[u][f] = ans;
    }
public:
    int countRoutes(std::vector<int>& locations, int start, int finish, int fuel) {
        std::memset(memo, -1, sizeof(memo));
        return dp(start, fuel, finish, locations);
    }
};

import java.util.*;

class Solution {
    int[][] memo;
    final int MOD = 1000000007;
    private int dp(int u, int f, int finish, int[] loc) {
        if (memo[u][f] != -1) return memo[u][f];
        int ans = (u == finish ? 1 : 0);
        int n = loc.length;
        for (int v = 0; v < n; v++) {
            if (v != u) {
                int cost = Math.abs(loc[u] - loc[v]);
                if (cost <= f) {
                    ans = (ans + dp(v, f - cost, finish, loc)) % MOD;
                }
            }
        }
        return memo[u][f] = ans;
    }
    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        int n = locations.length;
        memo = new int[n][fuel + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dp(start, fuel, finish, locations);
    }
}

var countRoutes = function(locations, start, finish, fuel) {
    const MOD = 1000000007;
    const n = locations.length;
    const memo = Array.from({ length: n }, () => new Int32Array(fuel + 1).fill(-1));
    function dp(u, f) {
        if (memo[u][f] !== -1) return memo[u][f];
        let ans = u === finish ? 1 : 0;
        for (let v = 0; v < n; v++) {
            if (v !== u) {
                const cost = Math.abs(locations[u] - locations[v]);
                if (cost <= f) {
                    ans = (ans + dp(v, f - cost)) % MOD;
                }
            }
        }
        return memo[u][f] = ans;
    }
    return dp(start, fuel);
};
